mapper.sql:
WHERE leave_requests.is_active = 1

   AND (( DATE(leave_requests.date_from) >= #{filter.dateFrom} AND DATE(leave_requests.date_to) >= #{filter.dateFrom} AND DATE(leave_requests.date_from) <= #{filter.dateTo} AND DATE(leave_requests.date_to) >= #{filter.dateTo} ) OR ( DATE(leave_requests.date_from) <= #{filter.dateFrom} AND DATE(leave_requests.date_to) >= #{filter.dateFrom} AND DATE(leave_requests.date_from) <= #{filter.dateTo} AND DATE(leave_requests.date_to) <= #{filter.dateTo} ) OR ( DATE(leave_requests.date_from) >= #{filter.dateFrom} AND DATE(leave_requests.date_to) >= #{filter.dateFrom} AND DATE(leave_requests.date_from) <= #{filter.dateTo} AND DATE(leave_requests.date_to) <= #{filter.dateTo} ) OR ( DATE(leave_requests.date_from) <= #{filter.dateFrom} AND DATE(leave_requests.date_to) >= #{filter.dateFrom} AND DATE(leave_requests.date_from) <= #{filter.dateTo} AND DATE(leave_requests.date_to) >= #{filter.dateTo} ) )


   AND YEAR(leave_requests.date_from) = #{filter.year}


   AND (employees.name LIKE CONCAT("%", #{filter.searchText}, "%") OR employees.name_kh LIKE CONCAT("%", #{filter.searchText}, "%") OR employees.code LIKE CONCAT("%", #{filter.searchText}, "%") OR employees.telephone LIKE CONCAT("%", #{filter.searchText}, "%") )


   AND leave_requests.employee_id = #{filter.employeesId}

mapper.delete:
UPDATE leave_requests SET
  is_active = 2,
  modified = NOW(),
  modified_by = #{userId}
WHERE id = #{id}

mapper.select:
SELECT
leave_requests.*,
leave_requests.note AS description,
leave_types.name AS leaveTypeName
FROM leave_requests
INNER JOIN leave_types ON leave_types.id = leave_requests.leave_type_id
WHERE leave_requests.is_active = 1

  AND
    (
      (
        DATE(leave_requests.date_from) >= #{filter.dateFrom} AND DATE(leave_requests.date_to) >= #{filter.dateFrom} AND
        DATE(leave_requests.date_from) <= #{filter.dateTo} AND DATE(leave_requests.date_to) >= #{filter.dateTo}
      ) OR (
        DATE(leave_requests.date_from) <= #{filter.dateFrom} AND DATE(leave_requests.date_to) >= #{filter.dateFrom} AND
        DATE(leave_requests.date_from) <= #{filter.dateTo} AND DATE(leave_requests.date_to) <= #{filter.dateTo}
      ) OR (
        DATE(leave_requests.date_from) >= #{filter.dateFrom} AND DATE(leave_requests.date_to) >= #{filter.dateFrom} AND
        DATE(leave_requests.date_from) <= #{filter.dateTo} AND DATE(leave_requests.date_to) <= #{filter.dateTo}
      ) OR (
        DATE(leave_requests.date_from) <= #{filter.dateFrom} AND DATE(leave_requests.date_to) >= #{filter.dateFrom} AND
        DATE(leave_requests.date_from) <= #{filter.dateTo} AND DATE(leave_requests.date_to) >= #{filter.dateTo}
      )
    )


  AND leave_requests.employee_id = #{filter.employeeId}

ORDER BY leave_types.id ASC
